H.background();
const w = H.W, h = H.H;
const A = P.A, T = Math.max(0.3, P.T), phi = P.phi;
const omega = 2 * Math.PI / T;
const x = A * Math.cos(omega * t + phi);
const vel = -A * omega * Math.sin(omega * t + phi);
// Left: position-vs-time graph
const v = H.plot2d({ xMin: 0, xMax: 4, yMin: -3.2, yMax: 3.2, box: { x: 60, y: 70, w: w * 0.52, h: h - 130 } });
v.grid(); v.axes();
v.line(0, A, 4, A, { color: H.colors.grid, width: 1, dash: [4, 4] });
v.line(0, -A, 4, -A, { color: H.colors.grid, width: 1, dash: [4, 4] });
v.fn(tau => A * Math.cos(omega * tau + phi), { color: H.colors.accent, width: 3 });
const tw = t % 4;
v.dot(tw, A * Math.cos(omega * tw + phi), { r: 6, fill: H.colors.warn });
v.text("x(t)", 3.4, A + 0.6, { color: H.colors.accent, size: 13 });
// Right: the oscillating particle on its axis
const ox = w * 0.82, oy0 = 70, oyH = h - 130;
const Yc = (xx) => oy0 + (oyH) * (1 - (xx + 3.2) / 6.4);
H.line(ox, oy0, ox, oy0 + oyH, { color: H.colors.axis, width: 1.5 });
H.line(ox - 26, Yc(0), ox + 26, Yc(0), { color: H.colors.grid, width: 1, dash: [4, 4] });
H.line(ox - 30, Yc(A), ox + 30, Yc(A), { color: H.colors.grid, width: 1, dash: [3, 3] });
H.line(ox - 30, Yc(-A), ox + 30, Yc(-A), { color: H.colors.grid, width: 1, dash: [3, 3] });
H.circle(ox, Yc(x), 12, { fill: H.colors.warn, stroke: H.colors.bg, width: 2 });
H.arrow(ox + 40, Yc(x), ox + 40, Yc(x) - vel * 18, { color: H.colors.good, width: 2.5 });
H.text("v", ox + 46, Yc(x) - 6, { color: H.colors.good, size: 12 });
H.text("Simple harmonic motion: x = A·cos(omega·t + phi)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("A = " + A.toFixed(2) + " m   T = " + T.toFixed(2) + " s   x = " + x.toFixed(2) + " m   v = " + vel.toFixed(2) + " m/s", 24, 52, { color: H.colors.sub, size: 13 });
